export interface CustomEmoji {
    id: string;
    name: string;
    src: string;
    tags: readonly string[];
}

export type VipReaction = CustomEmoji;

/**
 * Word-art emojis anyone may send inline or react with; they are never standalone stickers.
 * Art is generated by output/word-art-emoji/build.cjs; keep IDs in sync with the backend FREE_EMOJI_IDS.
 */
export const FREE_EMOJIS: readonly CustomEmoji[] = [
    {id: 'haha', name: 'Haha', tags: ['haha', 'hehe', 'lol', 'lmao', 'laugh', 'funny', 'word art']},
].map(emoji => ({...emoji, src: `/emoji/${emoji.id}.png`}));

