/** Every custom emoji usable inline or as a reaction, free ones first. */
export const CUSTOM_EMOJIS: readonly CustomEmoji[] = [...FREE_EMOJIS, ...VIP_REACTIONS];

const reactionPrefix = 'allchat:';
const reactionsByToken = new Map(CUSTOM_EMOJIS.map(reaction => [toCustomReactionToken(reaction.id), reaction]));
const customEmojisById = new Map(CUSTOM_EMOJIS.map(emoji => [emoji.id, emoji]));
const stickersById = new Map(VIP_REACTIONS.map(sticker => [sticker.id, sticker]));
const freeEmojiIds = new Set(FREE_EMOJIS.map(emoji => emoji.id));

/** Sticker messages use a short catalog ID, never a URL or a reaction token. */
export function getSticker(id?: string | null): VipReaction | undefined {
    return id ? stickersById.get(id) : undefined;
}

/** Inline emojis and reactions resolve against both the free and the VIP collections. */
export function getCustomEmoji(id?: string | null): CustomEmoji | undefined {
    return id ? customEmojisById.get(id) : undefined;
}

export function isFreeEmoji(id: string): boolean {
    return freeEmojiIds.has(id);
}

/** Unknown reserved tokens still count as VIP so they never bypass the upgrade prompt. */
export function isVipReactionToken(emoji?: string | null): boolean {
    return isCustomReactionToken(emoji) && !isFreeEmoji(emoji!.slice(reactionPrefix.length));
}

export function getStickerLabel(id?: string | null): string {
    const sticker = getSticker(id);
    return sticker ? `${sticker.name} sticker` : 'Unavailable sticker';
}

export function toCustomReactionToken(id: string): string {
    return `${reactionPrefix}${id}`;
}

/** Recognize even unavailable reserved tokens so they never render as URLs or raw IDs. */
export function isCustomReactionToken(emoji?: string | null): boolean {
    return Boolean(emoji?.startsWith(reactionPrefix));
}

/** Only an exact allowlisted identity may resolve an image. */
export function getCustomReaction(emoji?: string | null): CustomEmoji | undefined {
    return emoji ? reactionsByToken.get(emoji) : undefined;
}

export function getReactionLabel(emoji: string, emojiId?: string): string {
    const reaction = getCustomReaction(emoji);
    if (reaction) return reaction.name;
    if (isCustomReactionToken(emoji) || isCustomReactionToken(emojiId)) return 'Unavailable reaction';
    return emojiId?.replaceAll('_', ' ') || emoji;
}
